package dev.veltraph.client.fishing;

import dev.veltraph.client.config.*;
import dev.veltraph.client.fishing.module.FishingModule;
import dev.veltraph.client.scheduling.mc.FishingScheduledPausePort;
import org.junit.jupiter.api.Test;
import java.util.Random;
import static org.junit.jupiter.api.Assertions.*;

class FishingScheduledPauseTest {
    static class Services implements FishingServices {
        boolean available=true,rod=true,hook,bait,totem,support,grapple,golden,obstruction;String worm="IDLE";
        int starts,uses,callbacks,ticks;
        public boolean available(){return available;}public boolean hasFishingRod(){return rod;}public BobberFacts bobber(){return hook?new BobberFacts(true,0,false,false):BobberFacts.none();}
        public void useRod(){uses++;}public void startFishing(ConfigService c){starts++;}
        public boolean baitActive(){return bait;}public boolean totemActive(){return totem;}public boolean supportActive(){return support;}public boolean grappleActive(){return grapple;}public boolean goldenFishActive(){return golden;}public boolean obstructionActive(){return obstruction;}public String wormStatus(){return worm;}
        public void fishingActionBar(String s){callbacks++;}public void baitMessage(String s){callbacks++;}public void supportMessage(String s){callbacks++;}public void goldenFishMessage(String s){callbacks++;}
        public boolean tickWormHunting(boolean allow){ticks++;return false;}
    }
    static class Hooks implements FishingScheduledHooks {
        boolean ready=true,bind=true,resume=true;int releases,rebinds,resumes,cancels;Object ticket;
        public boolean ready(){return ready;}public boolean pause(Object t){ticket=t;releases++;return true;}public boolean rebind(Object t){rebinds++;return bind&&ticket==t;}public boolean resume(Object t){resumes++;return resume&&ticket==t;}public void cancel(Object t){if(ticket==t){cancels++;ticket=null;}}
    }
    @Test void enabledEngineCallbacksAndForeignTicketsRemainOwned(){var svc=new Services();var cfg=new MapConfigService();var m=new FishingModule(svc,cfg,new Random(0));m.setEnabled(true);var engine=m.runtimeIdentity();var hooks=new Hooks();var port=new FishingScheduledPausePort(m,hooks);Object own=new Object(),foreign=new Object();assertTrue(port.pause(own));assertFalse(port.pause(own));assertFalse(port.pause(foreign));assertEquals(1,hooks.releases);assertFalse(m.ownsGameplayInput());svc.available=false;for(int i=0;i<10;i++){m.onTick();m.onActionBar("1000/1000✎ Mana");m.onServerMessage("This Fishing Rod does not work in lava!");m.onServerMessage("You spot a Golden Fish surface from beneath the lava!");}assertTrue(m.isEnabled());assertEquals(0,svc.callbacks);assertEquals(0,svc.ticks);assertEquals(0,svc.uses);assertEquals(1,svc.starts);assertSame(engine,m.runtimeIdentity());assertFalse(port.rebindAfterOwnedArrival(foreign));assertFalse(port.resume(foreign));port.stop(foreign);assertTrue(m.isEnabled());assertFalse(port.resume(own));svc.available=true;assertTrue(port.rebindAfterOwnedArrival(own));assertTrue(m.isScheduledPaused());assertTrue(port.resume(own));assertSame(engine,m.runtimeIdentity());assertEquals(1,svc.starts);assertFalse(port.resume(own));m.onTick();assertEquals(1,svc.uses);}
    @Test void unsafeHookAndEachBorrowedFamilyAreDenied(){var s=new Services();var m=new FishingModule(s,new MapConfigService(),new Random(0));m.setEnabled(true);var h=new Hooks();var p=new FishingScheduledPausePort(m,h);Object t=new Object();s.hook=true;assertFalse(p.pause(t));s.hook=false;s.bait=true;assertFalse(p.pause(t));s.bait=false;s.totem=true;assertFalse(p.pause(t));s.totem=false;s.support=true;assertFalse(p.pause(t));s.support=false;s.grapple=true;assertFalse(p.pause(t));s.grapple=false;s.golden=true;assertFalse(p.pause(t));s.golden=false;s.obstruction=true;assertFalse(p.pause(t));s.obstruction=false;s.worm="REELING";assertFalse(p.pause(t));s.worm="IDLE";h.ready=false;assertFalse(p.pause(t));assertEquals(0,h.releases);assertTrue(m.isEnabled());}
    @Test void catchLedgerAndRemainingWorkDelaySurvivePause(){var f=new FishingRuntime(new Random(0),new FishingTuning(0,1000,false,10000,FishingDetectionMode.TRACKED_BITE,-.04));assertEquals(FishingAction.CAST,f.tick(in(false,false,0)));assertEquals(FishingAction.REEL,f.tick(in(true,true,100)));assertEquals(1,f.catchCount());Object t=new Object();assertTrue(f.suspendScheduled(t,200));assertEquals(FishingAction.NONE,f.tick(new FishingInputs(false,false,false,false,false,5000)));f.resumeAfterSubflow();assertEquals(FishingState.POST_CATCH_DELAY,f.state());assertEquals(1,f.catchCount());assertFalse(f.resumeScheduled(new Object(),5000));assertFalse(f.resumeScheduled(t,199));assertTrue(f.scheduledOwnedBy(t));assertTrue(f.resumeScheduled(t,5000));f.tick(in(false,false,5899));assertEquals(FishingState.POST_CATCH_DELAY,f.state());f.tick(in(false,false,5900));assertEquals(FishingState.NEED_CAST,f.state());assertEquals(1,f.catchCount());}
    private FishingInputs in(boolean hook,boolean bite,long now){return new FishingInputs(true,true,true,hook,bite,now);}
    @Test void manualStopAndChangedSettingsCannotRestartOldTicket(){var s=new Services();var cfg=new MapConfigService();var m=new FishingModule(s,cfg,new Random(0));m.setEnabled(true);var p=new FishingScheduledPausePort(m,new Hooks());Object old=new Object();assertTrue(p.pause(old));m.setEnabled(false);m.setEnabled(true);var fresh=m.runtimeIdentity();p.stop(old);assertTrue(m.isEnabled());assertFalse(p.resume(old));assertSame(fresh,m.runtimeIdentity());Object next=new Object();assertTrue(p.pause(next));cfg.set(FishingConfig.FISHING_CATCH_DELAY,9d);assertFalse(p.rebindAfterOwnedArrival(next));assertFalse(m.isEnabled());assertEquals(2,s.starts);}
    @Test void failedNativeRebindStopsWithoutEnableReset(){var s=new Services();var m=new FishingModule(s,new MapConfigService(),new Random(0));m.setEnabled(true);var h=new Hooks();var p=new FishingScheduledPausePort(m,h);Object t=new Object();assertTrue(p.pause(t));h.bind=false;assertFalse(p.rebindAfterOwnedArrival(t));assertFalse(m.isEnabled());assertEquals(1,s.starts);assertEquals(1,h.cancels);}
    @Test void timedOutUnacknowledgedCastIsNotASafePauseBoundary(){var f=new FishingRuntime(new Random(0),new FishingTuning(0,1000,false,100,FishingDetectionMode.TRACKED_BITE,-.04));f.tick(in(false,false,0));f.tick(in(false,false,101));assertEquals(FishingState.NEED_CAST,f.state());assertFalse(f.scheduledBoundary());assertFalse(f.suspendScheduled(new Object(),102));f.tick(in(true,false,103));assertEquals(FishingState.WAITING_BITE,f.state());f.tick(in(true,true,104));assertTrue(f.scheduledBoundary());}
}
